/// Compressor gain reduction: standard soft-knee formula.
///
/// Returns gain reduction in dB (positive value) for signals above threshold.
#[inline]
pub(super) fn compress_gr(input_db: f32, threshold: f32, ratio: f32, knee: f32) -> f32 {
    let slope = 1.0 - 1.0 / ratio.max(1.0);
    if knee < 0.1 {
        if input_db <= threshold {
            0.0
        } else {
            (input_db - threshold) * slope
        }
    } else if input_db < threshold - knee / 2.0 {
        0.0
    } else if input_db > threshold + knee / 2.0 {
        (input_db - threshold) * slope
    } else {
        let overshoot = input_db - threshold + knee / 2.0;
        let kf = overshoot / knee;
        kf * kf * (knee / 2.0) * slope
    }
}

/// Apply symmetric frequency-axis EMA smoothing to a spectral envelope.
///
/// Runs a forward pass (low-to-high) followed by a backward pass (high-to-low)
/// so that every bin is visited by both directions.
pub(super) fn smooth_spectral_envelope(envelope: &mut [f32], alpha: f32) {
    if envelope.len() < 2 {
        return;
    }
    let one_minus_alpha = 1.0 - alpha;
    // Forward pass
    let mut prev = envelope[0];
    for sample in envelope.iter_mut() {
        let smoothed = alpha * prev + one_minus_alpha * *sample;
        *sample = smoothed;
        prev = smoothed;
    }
    // Backward pass for symmetric smoothing
    prev = envelope[envelope.len() - 1];
    for sample in envelope.iter_mut().rev() {
        let smoothed = alpha * prev + one_minus_alpha * *sample;
        *sample = smoothed;
        prev = smoothed;
    }
}

